<?php
session_start();
require __DIR__ . '/db.php';
require __DIR__ . '/helpers.php';

header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('Expires: 0');
send_security_headers();

if (empty($_SESSION['user_id']) || (!passcode_is_pending() && !passcode_setup_is_pending())) {
    header('Location: ' . (is_fully_authenticated() ? 'estoque.php' : 'login.php'));
    exit;
}

$error = (string)($_GET['error'] ?? '');
$retryAfter = max(0, (int)($_GET['retry_after'] ?? 0));
$setupRequired = passcode_setup_is_pending();
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?= $setupRequired ? 'Configurar Pass Code' : 'Confirmar Pass Code' ?> — Uplar</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@500&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&display=swap" rel="stylesheet"><style>
:root{--navy:#061a46;--navy-soft:#0a2862;--p:#0877f9;--p-dark:#065fc7;--p-dim:rgba(8,119,249,.09);--ink:#12213a;--muted:#56647a;--faint:#8795aa;--bg:#f5f8fc;--card:#fff;--border:#dce5f0;--err:#ef4444;--err-dim:rgba(239,68,68,.09);--ok:#10b981}*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:Inter,sans-serif;background:var(--bg);color:var(--ink);-webkit-font-smoothing:antialiased}.auth-shell{min-height:100vh;display:grid;grid-template-columns:minmax(420px,1.08fr) minmax(400px,.92fr)}.story{position:relative;isolation:isolate;overflow:hidden;padding:clamp(2rem,4vw,4rem);display:flex;flex-direction:column;color:#fff;background:linear-gradient(140deg,var(--navy),var(--navy-soft) 66%,#0b3d74)}.story:before{content:'';position:absolute;inset:0;z-index:-1;background-image:linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);background-size:42px 42px;mask-image:linear-gradient(120deg,#000,transparent 85%)}.brand{display:flex;align-items:center;gap:.7rem;font-family:'Plus Jakarta Sans',sans-serif;font-weight:800}.brand-mark{display:grid;place-items:center;width:40px;height:40px;border:1px solid rgba(255,255,255,.16);border-radius:11px;background:rgba(255,255,255,.08);color:#68a9ff}.brand small{display:block;margin-top:2px;color:rgba(255,255,255,.5);font:500 .58rem 'JetBrains Mono',monospace;letter-spacing:.13em}.story-copy{margin:auto 0;max-width:30rem}.story-kicker{font:500 .65rem 'JetBrains Mono',monospace;letter-spacing:.13em;color:#8fe3d9;text-transform:uppercase}.story h2{margin:.9rem 0;font:800 clamp(2rem,4vw,3.4rem)/1.08 'Plus Jakarta Sans',sans-serif;letter-spacing:-.055em}.story p{max-width:34ch;color:rgba(230,239,255,.7);line-height:1.7}.access{display:grid;place-items:center;padding:1.5rem}.box{width:min(100%,430px);padding:1.7rem;border:1px solid var(--border);border-radius:16px;background:var(--card);box-shadow:0 14px 38px rgba(12,38,79,.08);text-align:center}.shield{display:grid;place-items:center;width:42px;height:42px;margin:0 auto .85rem;border-radius:12px;background:var(--p-dim);color:var(--p)}.shield span{font-size:1.35rem}.eyebrow{margin-bottom:.55rem;color:var(--p);font:500 .63rem 'JetBrains Mono',monospace;letter-spacing:.1em;text-transform:uppercase}.box h1{margin:0;font:800 1.38rem/1.2 'Plus Jakarta Sans',sans-serif;letter-spacing:-.04em}.box>p{margin:.42rem 0 1.35rem;color:var(--muted);font-size:.85rem}.notice{margin:-.2rem 0 1rem;padding:.68rem .75rem;border-radius:9px;background:var(--err-dim);color:#b91c1c;font-size:.78rem;text-align:left}.pin-widget{position:relative;max-width:340px;margin:0 auto}.pin-input{position:absolute;inset:0;width:100%;height:58px;opacity:.01;cursor:text;z-index:2}.pin-slots{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.pin-slot{height:58px;display:grid;place-items:center;border:1px solid var(--border);border-radius:10px;background:#fff;transition:border-color .16s,background .16s,box-shadow .16s,transform .16s}.pin-slot.filled:after{content:'•';font-size:1.55rem;line-height:1;color:var(--ink);transform:scale(.96);animation:pop .16s ease-out forwards}.pin-widget.focused .pin-slot.active{border-color:var(--p);background:#f8fbff;box-shadow:0 0 0 3px var(--p-dim)}.pin-widget.error .pin-slot{border-color:var(--err);background:#fffafa}.pin-widget.error .pin-slots{animation:shake .26s ease-in-out}.field-label{display:block;margin:1rem 0 .48rem;text-align:left;color:var(--muted);font-size:.74rem;font-weight:700}.primary{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;width:100%;min-height:44px;margin-top:1.2rem;border:0;border-radius:9px;background:var(--p);color:#fff;font:700 .84rem Inter,sans-serif;cursor:pointer}.primary:hover{background:var(--p-dark)}.primary:disabled{opacity:.58;cursor:not-allowed}.links{margin-top:1rem}.text-btn{border:0;background:transparent;color:var(--muted);font:600 .78rem Inter,sans-serif;cursor:pointer}@keyframes pop{to{transform:scale(1)}}@keyframes spin{to{transform:rotate(360deg)}}.pin-widget.verifying .pin-slot{border-color:var(--p);background:#f8fbff;animation:pulse .32s ease-in-out infinite alternate}.pin-widget.verifying .pin-slot.filled:after{color:var(--p)} @keyframes pulse{to{box-shadow:0 0 0 3px var(--p-dim)}}@keyframes shake{25%{transform:translateX(-4px)}75%{transform:translateX(4px)}}@media(max-width:800px){.auth-shell{display:block}.story{min-height:auto;padding:1.25rem 1.35rem}.story-copy{display:none}.access{min-height:calc(100vh - 78px);padding:1rem}.box{padding:1.45rem 1.1rem;box-shadow:none;border:0;background:transparent}.pin-slots{gap:6px}.pin-slot,.pin-input{height:52px}}@media(max-width:360px){.pin-slots{gap:5px}.pin-slot,.pin-input{height:47px;border-radius:8px}}
</style></head><body><div class="auth-shell"><aside class="story"><div class="brand"><span class="brand-mark material-symbols-outlined">cloud</span><span>UPLAR<small>Estoque</small></span></div><div class="story-copy"><div class="story-kicker">Proteção adicional</div><h2>Seu acesso,<br>sob controle.</h2><p>Uma etapa rápida para manter a sua operação protegida.</p></div></aside><main class="access"><section class="box" aria-labelledby="passcode-title"><div class="shield"><span class="material-symbols-outlined" aria-hidden="true">shield_lock</span></div><div class="eyebrow">Proteção adicional</div><h1 id="passcode-title"><?= $setupRequired ? 'Crie seu Pass Code' : 'Confirme seu acesso' ?></h1><p><?= $setupRequired ? 'Escolha e confirme 6 números para continuar.' : 'Digite seu Pass Code para continuar.' ?></p><?php if ($error !== ''): ?><div class="notice" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if ($setupRequired): ?><form action="passcode_action.php" method="post" autocomplete="off" id="setup-form"><input type="hidden" name="action" value="setup"><?= csrf_input() ?><div class="pin-widget" data-pin><label class="field-label" for="new-passcode">Novo Pass Code</label><input class="pin-input" id="new-passcode" name="passcode" type="password" inputmode="numeric" autocomplete="new-password" maxlength="6" pattern="[0-9]{6}" required><div class="pin-slots" aria-hidden="true"></div></div><div class="pin-widget" data-pin><label class="field-label" for="confirm-passcode">Confirme o Pass Code</label><input class="pin-input" id="confirm-passcode" name="passcode_confirm" type="password" inputmode="numeric" autocomplete="new-password" maxlength="6" pattern="[0-9]{6}" required><div class="pin-slots" aria-hidden="true"></div></div><button class="primary" type="submit" disabled>Configurar e continuar</button></form><?php else: ?><form action="passcode_action.php" method="post" autocomplete="off" id="verify-form"><input type="hidden" name="action" value="verify"><?= csrf_input() ?><div class="pin-widget<?= $error !== '' ? ' error' : '' ?>" data-pin data-autosubmit><label class="field-label" for="passcode">Pass Code de 6 dígitos</label><input class="pin-input" id="passcode" name="passcode" type="password" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" required<?= $retryAfter ? ' disabled' : '' ?> autofocus><div class="pin-slots" aria-hidden="true"></div></div><button class="primary" type="submit"<?= $retryAfter ? ' disabled' : '' ?>><?= $retryAfter ? 'Tente novamente em ' . $retryAfter . 's' : 'Continuar' ?></button></form><div class="links"><button class="text-btn" type="submit" form="logout-form">Sair da conta</button></div><?php endif; ?><form id="logout-form" action="logout.php" method="post"><?= csrf_input() ?></form></section></main></div><script>
document.querySelectorAll('[data-pin]').forEach(widget=>{const input=widget.querySelector('.pin-input'),slots=widget.querySelector('.pin-slots'),initialError=widget.classList.contains('error');for(let i=0;i<6;i++){const s=document.createElement('span');s.className='pin-slot';slots.appendChild(s)}const render=()=>{const value=input.value.replace(/\D/g,'').slice(0,6);if(input.value!==value)input.value=value;slots.querySelectorAll('.pin-slot').forEach((slot,i)=>slot.className='pin-slot'+(i<value.length?' filled':'')+(i===value.length?' active':''));if(value)widget.classList.remove('error');const submit=widget.hasAttribute('data-autosubmit')&&value.length===6;if(submit){const form=input.form,button=form.querySelector('.primary');if(!form.dataset.submitting){form.dataset.submitting='1';widget.classList.add('verifying');button.disabled=true;button.innerHTML='<span class="material-symbols-outlined" style="font-size:1rem;animation:spin .8s linear infinite">progress_activity</span>Verificando…';setTimeout(()=>form.requestSubmit(),320)}}const setup=document.getElementById('setup-form');if(setup){const a=document.getElementById('new-passcode').value,b=document.getElementById('confirm-passcode').value;setup.querySelector('.primary').disabled=!(a.length===6&&b.length===6)}};input.addEventListener('input',render);input.addEventListener('focus',()=>widget.classList.add('focused'));input.addEventListener('blur',()=>widget.classList.remove('focused'));widget.addEventListener('click',()=>input.focus());render();if(initialError)setTimeout(()=>widget.classList.remove('error'),360)});
</script></body></html>
